-- Упражнения книги 19, глава 22 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-mode-string', 0, 'func', 'Строка прав как у ls -l', 'Напишите mode_string(mode): по целому st_mode файла (вместе с битами типа) верните 10-символьную строку, как её печатают ls -l и stat.filemode. Первый символ — тип по старшим битам (mode & 0o170000): 0o140000 s, 0o120000 l, 0o100000 -, 0o060000 b, 0o040000 d, 0o020000 c, 0o010000 p, любое другое значение ?. Дальше три тройки r, w, x или - для владельца, группы и остальных. Позиция x владельца показывает s, если стоит setuid (0o4000) и есть x, и S, если setuid стоит без x; группа так же с setgid (0o2000); позиция x остальных показывает t, если стоит sticky (0o1000) и есть x, и T, если x нет.', 'def mode_string(mode):
    pass
', 'Для каждой из трёх троек возьмите (mode >> сдвиг) & 7; особый бит меняет только третий символ тройки.', '{"func": "mode_string", "tests": [{"args": [33188], "expected": "-rw-r--r--"}, {"args": [33261], "expected": "-rwxr-xr-x"}, {"args": [16877], "expected": "drwxr-xr-x"}, {"args": [41471], "expected": "lrwxrwxrwx"}, {"args": [35309], "expected": "-rwsr-xr-x"}, {"args": [35236], "expected": "-rwSr--r--"}, {"args": [34285], "expected": "-rwxr-sr-x"}, {"args": [34213], "expected": "-rw-r-Sr-x"}, {"args": [17407], "expected": "drwxrwxrwt"}, {"args": [17406], "expected": "drwxrwxrwT"}, {"args": [25008], "expected": "brw-rw----"}, {"args": [8592], "expected": "crw--w----"}, {"args": [4516], "expected": "prw-r--r--"}, {"args": [49645], "expected": "srwxr-xr-x"}, {"args": [32768], "expected": "----------"}, {"args": [36351], "expected": "-rwsrwsrwx"}, {"args": [17917], "expected": "drwxrwsr-x"}, {"args": [17908], "expected": "drwxrwSr--"}, {"args": [420], "expected": "?rw-r--r--"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-chmod', 1, 'func', 'Символьный chmod с umask', 'Реализуйте упрощённый символьный режим GNU chmod: apply_chmod(mode, spec, umask, is_dir) возвращает новые биты прав (целое 0..0o7777, особые биты включены). spec — клаузы через запятую, применяются слева направо, каждая к результату предыдущей. Клауза: ноль или больше букв who из u, g, o, a, затем одно или больше действий; действие — оператор (+, -, =), за которым идут ноль или больше букв прав r, w, x, X, s, t либо ровно одна буква u, g или o. a означает ugo; пустой who тоже означает ugo, но тогда из value перед применением оператора убираются rwx-биты umask. Каждый класс владеет своими rwx-битами и одним особым: u — setuid 0o4000, g — setgid 0o2000, o — sticky 0o1000; affected — это все биты, которыми владеют названные классы. Буквы r, w, x дают 4, 2, 1 в каждом названном классе; X — как x, но только если is_dir истинно или в текущем mode есть любой бит x; s даёт 0o6000, t даёт 0o1000; value затем пересекается с affected, поэтому o+s и u+t ничего не меняют. Буква u, g или o вместо прав копирует текущую rwx-тройку этого класса в каждый названный класс. Оператор +: mode |= value; -: mode &= ~value; =: сначала очищаются все affected-биты, затем добавляется value. Особое поведение chmod для setuid/setgid каталогов не моделируется.', 'def apply_chmod(mode, spec, umask, is_dir):
    pass
', 'Разберите клаузу посимвольно: сначала who, потом цикл «оператор + буквы». Для каждого действия посчитайте value, пересеките с affected, затем примените оператор.', '{"func": "apply_chmod", "tests": [{"args": [420, "u+x", 18, false], "expected": 484}, {"args": [420, "a+x", 18, false], "expected": 493}, {"args": [420, "+x", 63, false], "expected": 484}, {"args": [511, "go-w", 18, false], "expected": 493}, {"args": [416, "o=g", 18, false], "expected": 420}, {"args": [384, "u=rwx,go=rx", 18, false], "expected": 493}, {"args": [420, "a+X", 18, false], "expected": 420}, {"args": [484, "a+X", 18, false], "expected": 493}, {"args": [420, "a+X", 18, true], "expected": 493}, {"args": [493, "u+s,g+s", 18, false], "expected": 3565}, {"args": [493, "o+t", 18, true], "expected": 1005}, {"args": [493, "u+t", 18, false], "expected": 493}, {"args": [2541, "u-s", 18, false], "expected": 493}, {"args": [511, "=r", 18, false], "expected": 292}, {"args": [511, "=rw", 63, false], "expected": 384}, {"args": [438, "-w", 18, false], "expected": 310}, {"args": [416, "ug=rw,o=", 18, false], "expected": 432}, {"args": [493, "a=", 18, true], "expected": 0}, {"args": [384, "u+x-w,g=u", 18, false], "expected": 360}, {"args": [1512, "g-s,o+r", 23, true], "expected": 492}, {"args": [420, "u+x,g=u", 18, false], "expected": 508}, {"args": [2048, "ugo+s", 18, false], "expected": 3072}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-safe-join', 2, 'func', 'Безопасное соединение путей', 'Напишите safe_join(base, name, links): верните разрешённый абсолютный путь base/name, если он лежит внутри разрешённого base (или равен ему), иначе None. base — нормализованный абсолютный путь без завершающего слэша (или /), name пришло снаружи. links — словарь «абсолютный путь символической ссылки → строка-цель» (цель может быть абсолютной или относительной и содержать ..); все пути, которых нет в links, считаются обычными каталогами или файлами. Соединение как у оператора / в pathlib: если name начинается с /, результат — сам name, иначе base + ''/'' + name. Разрешение — как в ядре Linux: компоненты обрабатываются слева направо; пустые и . пропускаются; .. убирает последний компонент уже накопленного результата (у корня остаётся корень); если накопленный путь плюс очередной компонент есть в links, это раскрытие ссылки: относительная цель обрабатывается от каталога, содержащего ссылку, абсолютная — от корня, остаток исходного пути продолжается после цели. Больше 40 раскрытий за одно разрешение — None. base тоже разрешается этими правилами (если там больше 40 раскрытий — None). Результат — разрешённый путь: без /, ., .. и повторных слэшей, корень — «/».', 'def safe_join(base, name, links):
    pass
', 'Держите стек оставшихся компонентов: при раскрытии ссылки положите компоненты цели обратно на стек. Сравнивайте как текст: rj == rb или rj начинается с rb + ''/''.', '{"func": "safe_join", "tests": [{"args": ["/srv/app", "conf/a.ini", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app/conf/a.ini"}, {"args": ["/srv/app", "./conf//a.ini", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app/conf/a.ini"}, {"args": ["/srv/app", "../app/x", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app/x"}, {"args": ["/srv/app", "../secret", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": null}, {"args": ["/srv/app", "data/x", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": null}, {"args": ["/srv/app", "cur/file", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app/releases/v2/file"}, {"args": ["/srv/app", "cur/etc/passwd", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": null}, {"args": ["/srv/app", "cur/../x", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app/releases/x"}, {"args": ["/srv/app", "up/x", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": null}, {"args": ["/srv/app", "/srv/app/y", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app/y"}, {"args": ["/srv/app", "/etc/passwd", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": null}, {"args": ["/srv/app", "", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app"}, {"args": ["/srv/app", "a/x", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": null}, {"args": ["/srv/app", "rel/z", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app/conf/z"}, {"args": ["/srv/current", "x", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": "/srv/app-1/x"}, {"args": ["/srv/current", "../app-2/x", {"/srv/app/data": "/var/data", "/srv/app/cur": "releases/v2", "/srv/app/releases/v2/etc": "/etc", "/srv/app/up": "..", "/srv/app/a": "b", "/srv/app/b": "a", "/srv/current": "/srv/app-1", "/srv/app/rel": "../app/conf"}], "expected": null}, {"args": ["/", "../../x", {}], "expected": "/x"}, {"args": ["/srv/app", "x/../../..", {}], "expected": null}, {"args": ["/srv/app", "x/../y/./z", {}], "expected": "/srv/app/y/z"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-enospc', 3, 'func', 'Полный диск: что останется', 'Скрипт обновляет файл на маленьком диске либо на месте, либо через временный файл. Напишите enospc_outcome(files, ops, target, free): files — словарь «абсолютный путь → текст» (один символ — один байт), ops — операции по порядку, target — интересующий путь, free — число свободных байт. Операции: ("open_trunc", p) создаёт p или обнуляет его (байты старого содержимого освобождаются); ("write", p, text) дописывает text в p, если len(text) <= free (free уменьшается); иначе дописываются только первые free символов, free становится 0 и скрипт падает с ENOSPC на этом месте, дальнейшие операции не выполняются; ("rename", src, dst) переносит src в dst, байты прежнего dst, если он был, освобождаются; ("unlink", p) удаляет p, его байты освобождаются; любая другая операция (например, fsync) ничего не меняет. Верните кортеж (содержимое target или None, если файла нет, отсортированный список всех остальных существующих путей).', 'def enospc_outcome(files, ops, target, free):
    pass
', 'Ведите словарь fs и счётчик free; при нехватке места допишите text[:free] и сделайте break.', '{"func": "enospc_outcome", "tests": [{"args": [{"/etc/app.conf": "OLDOLD"}, [{"__tuple__": ["open_trunc", "/etc/app.conf"]}, {"__tuple__": ["write", "/etc/app.conf", "NEW1"]}, {"__tuple__": ["write", "/etc/app.conf", "NEW2"]}, {"__tuple__": ["fsync", "/etc/app.conf"]}], "/etc/app.conf", 0], "expected": {"__tuple__": ["NEW1NE", []]}}, {"args": [{"/etc/app.conf": "OLDOLD"}, [{"__tuple__": ["open_trunc", "/etc/app.conf"]}, {"__tuple__": ["write", "/etc/app.conf", "NEW1"]}, {"__tuple__": ["write", "/etc/app.conf", "NEW2"]}, {"__tuple__": ["fsync", "/etc/app.conf"]}], "/etc/app.conf", 1], "expected": {"__tuple__": ["NEW1NEW", []]}}, {"args": [{"/etc/app.conf": "OLDOLD"}, [{"__tuple__": ["open_trunc", "/etc/app.conf"]}, {"__tuple__": ["write", "/etc/app.conf", "NEW1"]}, {"__tuple__": ["write", "/etc/app.conf", "NEW2"]}, {"__tuple__": ["fsync", "/etc/app.conf"]}], "/etc/app.conf", 20], "expected": {"__tuple__": ["NEW1NEW2", []]}}, {"args": [{"/etc/app.conf": "OLDOLD"}, [{"__tuple__": ["open_trunc", "/etc/.app.conf.tmp"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "NEW1"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "NEW2"]}, {"__tuple__": ["fsync", "/etc/.app.conf.tmp"]}, {"__tuple__": ["rename", "/etc/.app.conf.tmp", "/etc/app.conf"]}], "/etc/app.conf", 0], "expected": {"__tuple__": ["OLDOLD", ["/etc/.app.conf.tmp"]]}}, {"args": [{"/etc/app.conf": "OLDOLD"}, [{"__tuple__": ["open_trunc", "/etc/.app.conf.tmp"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "NEW1"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "NEW2"]}, {"__tuple__": ["fsync", "/etc/.app.conf.tmp"]}, {"__tuple__": ["rename", "/etc/.app.conf.tmp", "/etc/app.conf"]}], "/etc/app.conf", 5], "expected": {"__tuple__": ["OLDOLD", ["/etc/.app.conf.tmp"]]}}, {"args": [{"/etc/app.conf": "OLDOLD"}, [{"__tuple__": ["open_trunc", "/etc/.app.conf.tmp"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "NEW1"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "NEW2"]}, {"__tuple__": ["fsync", "/etc/.app.conf.tmp"]}, {"__tuple__": ["rename", "/etc/.app.conf.tmp", "/etc/app.conf"]}], "/etc/app.conf", 8], "expected": {"__tuple__": ["NEW1NEW2", []]}}, {"args": [{"/etc/app.conf": "OLDOLD"}, [{"__tuple__": ["open_trunc", "/etc/.app.conf.tmp"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "NEW1"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "NEW2"]}, {"__tuple__": ["fsync", "/etc/.app.conf.tmp"]}, {"__tuple__": ["rename", "/etc/.app.conf.tmp", "/etc/app.conf"]}, {"__tuple__": ["unlink", "/etc/gone"]}], "/etc/app.conf", 8], "expected": {"__tuple__": ["NEW1NEW2", []]}}, {"args": [{"/etc/app.conf": "ab", "/etc/other": "xyz"}, [{"__tuple__": ["open_trunc", "/etc/.app.conf.tmp"]}, {"__tuple__": ["write", "/etc/.app.conf.tmp", "12345"]}, {"__tuple__": ["unlink", "/etc/app.conf"]}, {"__tuple__": ["rename", "/etc/.app.conf.tmp", "/etc/app.conf"]}], "/etc/app.conf", 3], "expected": {"__tuple__": ["ab", ["/etc/.app.conf.tmp", "/etc/other"]]}}, {"args": [{}, [{"__tuple__": ["open_trunc", "/etc/app.conf"]}, {"__tuple__": ["write", "/etc/app.conf", "hello"]}], "/etc/app.conf", 5], "expected": {"__tuple__": ["hello", []]}}, {"args": [{"/etc/app.conf": "AAAA"}, [{"__tuple__": ["open_trunc", "/etc/app.conf"]}, {"__tuple__": ["write", "/etc/app.conf", "BB"]}, {"__tuple__": ["open_trunc", "/etc/app.conf"]}, {"__tuple__": ["write", "/etc/app.conf", "CCCCCC"]}], "/etc/app.conf", 0], "expected": {"__tuple__": ["CCCC", []]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-fsync-audit', 4, 'func', 'Аудит атомарной замены', 'Напишите fsync_audit(ops, mounts): найдите ошибки порядка в последовательности атомарной замены файла. mounts — список точек монтирования (всегда есть "/"); файловая система пути — самая длинная точка монтирования m, для которой путь равен m или начинается с m + "/". ops — кортежи: ("write", p) — в p записаны данные (файл «грязный»); ("fsync", p) — p сброшен на диск (становится чистым); ("rename", src, dst); ("fsync_dir", d). Правила, проблемы добавляются в список в порядке событий. При rename: если src грязный, добавьте "DATA_NOT_SYNCED " + src. Затем, если файловые системы src и dst разные, добавьте "EXDEV " + src + " " + dst, и переименование считается невыполненным (дальше для него ничего не делается). Иначе переименование выполнено: грязность src переходит на dst, а каталоги src и dst (родитель пути — всё до последнего /, для файла в корне это "/") становятся «ожидающими» fsync_dir. fsync_dir d снимает ожидание с d. В конце для каждого оставшегося ожидающего каталога по возрастанию имени добавьте "DIR_NOT_SYNCED " + каталог. Верните список проблем.', 'def fsync_audit(ops, mounts):
    pass
', 'Три множества: грязные файлы, ожидающие каталоги и список проблем. fs_of: перебор mounts с выбором самого длинного совпадения.', '{"func": "fsync_audit", "tests": [{"args": [[{"__tuple__": ["write", "/etc/app.conf.tmp"]}, {"__tuple__": ["fsync", "/etc/app.conf.tmp"]}, {"__tuple__": ["rename", "/etc/app.conf.tmp", "/etc/app.conf"]}, {"__tuple__": ["fsync_dir", "/etc"]}], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": []}, {"args": [[{"__tuple__": ["write", "/etc/app.conf.tmp"]}, {"__tuple__": ["rename", "/etc/app.conf.tmp", "/etc/app.conf"]}, {"__tuple__": ["fsync_dir", "/etc"]}], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": ["DATA_NOT_SYNCED /etc/app.conf.tmp"]}, {"args": [[{"__tuple__": ["write", "/etc/app.conf.tmp"]}, {"__tuple__": ["fsync", "/etc/app.conf.tmp"]}, {"__tuple__": ["rename", "/etc/app.conf.tmp", "/etc/app.conf"]}], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": ["DIR_NOT_SYNCED /etc"]}, {"args": [[{"__tuple__": ["write", "/tmp/new"]}, {"__tuple__": ["fsync", "/tmp/new"]}, {"__tuple__": ["rename", "/tmp/new", "/boot/grub.cfg"]}, {"__tuple__": ["fsync_dir", "/boot"]}], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": ["EXDEV /tmp/new /boot/grub.cfg"]}, {"args": [[{"__tuple__": ["write", "/var/lib/vdsm/a.tmp"]}, {"__tuple__": ["fsync", "/var/lib/vdsm/a.tmp"]}, {"__tuple__": ["rename", "/var/lib/vdsm/a.tmp", "/var/lib/vdsm/conf/a"]}, {"__tuple__": ["fsync_dir", "/var/lib/vdsm"]}, {"__tuple__": ["fsync_dir", "/var/lib/vdsm/conf"]}], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": []}, {"args": [[{"__tuple__": ["write", "/var/lib/vdsm/a.tmp"]}, {"__tuple__": ["fsync", "/var/lib/vdsm/a.tmp"]}, {"__tuple__": ["write", "/var/lib/vdsm/a.tmp"]}, {"__tuple__": ["rename", "/var/lib/vdsm/a.tmp", "/var/lib/vdsm/conf/a"]}, {"__tuple__": ["fsync_dir", "/var/lib/vdsm/conf"]}], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": ["DATA_NOT_SYNCED /var/lib/vdsm/a.tmp", "DIR_NOT_SYNCED /var/lib/vdsm"]}, {"args": [[{"__tuple__": ["write", "/data/x.tmp"]}, {"__tuple__": ["fsync", "/data/x.tmp"]}, {"__tuple__": ["rename", "/data/x.tmp", "/data/x"]}, {"__tuple__": ["fsync_dir", "/data"]}, {"__tuple__": ["rename", "/data/x", "/etc/x"]}], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": ["EXDEV /data/x /etc/x"]}, {"args": [[{"__tuple__": ["rename", "/etc/a", "/etc/b"]}, {"__tuple__": ["fsync_dir", "/etc"]}], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": []}, {"args": [[], ["/", "/boot", "/var/lib/vdsm", "/data"]], "expected": []}, {"args": [[{"__tuple__": ["write", "/etc/a.tmp"]}, {"__tuple__": ["fsync", "/etc/a.tmp"]}, {"__tuple__": ["rename", "/etc/a.tmp", "/etc/a"]}, {"__tuple__": ["fsync_dir", "/etc"]}, {"__tuple__": ["write", "/etc/b.tmp"]}, {"__tuple__": ["rename", "/etc/b.tmp", "/etc/b"]}], ["/"]], "expected": ["DATA_NOT_SYNCED /etc/b.tmp", "DIR_NOT_SYNCED /etc"]}, {"args": [[{"__tuple__": ["write", "/boot/x"]}, {"__tuple__": ["fsync", "/boot/x"]}, {"__tuple__": ["rename", "/boot/x", "/boot/efi/x"]}, {"__tuple__": ["fsync_dir", "/boot"]}, {"__tuple__": ["fsync_dir", "/boot/efi"]}], ["/", "/boot", "/boot/efi"]], "expected": ["EXDEV /boot/x /boot/efi/x"]}, {"args": [[{"__tuple__": ["write", "/boot/x"]}, {"__tuple__": ["fsync", "/boot/x"]}, {"__tuple__": ["rename", "/boot/x", "/boot/efi/x"]}], ["/", "/boot", "/boot/efi"]], "expected": ["EXDEV /boot/x /boot/efi/x"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-lock-trace', 5, 'func', 'Лок-файл, устаревшая блокировка и PID', 'Смоделируйте протокол лок-файла с O_EXCL. lock_trace(events, alive): events — список (pid, action), alive — список PID живых процессов в начале. В начале лок-файла нет. Действия: "acquire" — если лок-файла нет, он создаётся с владельцем pid, результат "acquired"; если файл есть, читается PID владельца: если он среди живых, результат "busy"; иначе блокировка устарела, файл удаляется и создаётся заново с владельцем pid, результат "stolen". "release" — если файл есть и его владелец pid, файл удаляется, результат "released", иначе "not-owner" и файл не трогается. "die" — pid убирается из живых, лок-файл остаётся, результат "died". "spawn" — pid добавляется к живым (так PID умершего владельца может достаться чужому процессу), результат "spawned". Верните список результатов в порядке событий.', 'def lock_trace(events, alive):
    pass
', 'Достаточно двух переменных: owner (или None) и множества alive.', '{"func": "lock_trace", "tests": [{"args": [[{"__tuple__": [10, "acquire"]}, {"__tuple__": [11, "acquire"]}, {"__tuple__": [10, "release"]}, {"__tuple__": [11, "acquire"]}], [10, 11]], "expected": ["acquired", "busy", "released", "acquired"]}, {"args": [[{"__tuple__": [10, "acquire"]}, {"__tuple__": [10, "die"]}, {"__tuple__": [11, "acquire"]}, {"__tuple__": [11, "release"]}], [10, 11]], "expected": ["acquired", "died", "stolen", "released"]}, {"args": [[{"__tuple__": [10, "acquire"]}, {"__tuple__": [11, "release"]}, {"__tuple__": [10, "release"]}, {"__tuple__": [10, "release"]}], [10, 11]], "expected": ["acquired", "not-owner", "released", "not-owner"]}, {"args": [[{"__tuple__": [10, "acquire"]}, {"__tuple__": [10, "die"]}, {"__tuple__": [10, "spawn"]}, {"__tuple__": [11, "acquire"]}], [10, 11]], "expected": ["acquired", "died", "spawned", "busy"]}, {"args": [[{"__tuple__": [10, "acquire"]}, {"__tuple__": [10, "die"]}, {"__tuple__": [12, "acquire"]}, {"__tuple__": [11, "acquire"]}, {"__tuple__": [12, "die"]}, {"__tuple__": [11, "acquire"]}], [10, 11, 12]], "expected": ["acquired", "died", "stolen", "busy", "died", "stolen"]}, {"args": [[{"__tuple__": [5, "acquire"]}, {"__tuple__": [5, "acquire"]}], [5]], "expected": ["acquired", "busy"]}, {"args": [[{"__tuple__": [7, "spawn"]}, {"__tuple__": [7, "acquire"]}, {"__tuple__": [8, "acquire"]}, {"__tuple__": [7, "die"]}, {"__tuple__": [8, "acquire"]}, {"__tuple__": [7, "release"]}, {"__tuple__": [8, "release"]}], [8]], "expected": ["spawned", "acquired", "busy", "died", "stolen", "not-owner", "released"]}, {"args": [[], []], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-flock-sim', 6, 'func', 'Семантика flock', 'Смоделируйте flock(2) для одного файла. flock_sim(ops) возвращает список результатов, по одному на операцию. Операции: ("open", fd) — новое открытое файловое описание, к которому ведёт дескриптор fd; ("dup", fd, new_fd) — new_fd указывает на то же описание (dup или fork); ("close", fd) — дескриптор закрывается, а блокировка описания снимается, когда закрыт последний ведущий к нему дескриптор; ("flock", fd, mode, nonblock), где mode — "SH", "EX" или "UN". Результат open, dup и close — "ok". Блокировка принадлежит описанию, а не дескриптору. flock: сначала в любом случае снимается блокировка, которую описание уже держало (конверсия неатомарна), затем при mode "UN" результат "ok"; иначе запрос конфликтует, если другое описание держит "EX", либо если запрашивается "EX", а другое описание держит любую блокировку. Конфликт даёт "EWOULDBLOCK" при nonblock истинном и "BLOCKS" при ложном (в обоих случаях блокировка не взята); без конфликта блокировка берётся и результат "ok".', 'def flock_sim(ops):
    pass
', 'Два словаря: fd → номер описания и номер описания → режим. При close смотрите, остались ли ещё дескрипторы на это описание.', '{"func": "flock_sim", "tests": [{"args": [[{"__tuple__": ["open", "a"]}, {"__tuple__": ["open", "b"]}, {"__tuple__": ["flock", "a", "EX", true]}, {"__tuple__": ["flock", "b", "EX", true]}, {"__tuple__": ["flock", "a", "UN", true]}, {"__tuple__": ["flock", "b", "EX", true]}]], "expected": ["ok", "ok", "ok", "EWOULDBLOCK", "ok", "ok"]}, {"args": [[{"__tuple__": ["open", "a"]}, {"__tuple__": ["open", "b"]}, {"__tuple__": ["flock", "a", "SH", true]}, {"__tuple__": ["flock", "b", "SH", true]}, {"__tuple__": ["flock", "a", "EX", true]}, {"__tuple__": ["flock", "b", "EX", true]}]], "expected": ["ok", "ok", "ok", "ok", "EWOULDBLOCK", "ok"]}, {"args": [[{"__tuple__": ["open", "a"]}, {"__tuple__": ["dup", "a", "a2"]}, {"__tuple__": ["flock", "a", "EX", true]}, {"__tuple__": ["open", "b"]}, {"__tuple__": ["close", "a"]}, {"__tuple__": ["flock", "b", "SH", true]}, {"__tuple__": ["close", "a2"]}, {"__tuple__": ["flock", "b", "SH", true]}]], "expected": ["ok", "ok", "ok", "ok", "ok", "EWOULDBLOCK", "ok", "ok"]}, {"args": [[{"__tuple__": ["open", "a"]}, {"__tuple__": ["open", "b"]}, {"__tuple__": ["flock", "a", "EX", false]}, {"__tuple__": ["flock", "b", "SH", false]}, {"__tuple__": ["flock", "b", "SH", true]}]], "expected": ["ok", "ok", "ok", "BLOCKS", "EWOULDBLOCK"]}, {"args": [[{"__tuple__": ["open", "a"]}, {"__tuple__": ["open", "b"]}, {"__tuple__": ["flock", "a", "EX", true]}, {"__tuple__": ["flock", "a", "EX", true]}, {"__tuple__": ["flock", "b", "EX", true]}]], "expected": ["ok", "ok", "ok", "ok", "EWOULDBLOCK"]}, {"args": [[{"__tuple__": ["open", "a"]}, {"__tuple__": ["open", "b"]}, {"__tuple__": ["open", "c"]}, {"__tuple__": ["flock", "a", "SH", true]}, {"__tuple__": ["flock", "b", "SH", true]}, {"__tuple__": ["flock", "c", "EX", true]}, {"__tuple__": ["flock", "a", "UN", true]}, {"__tuple__": ["flock", "b", "UN", true]}, {"__tuple__": ["flock", "c", "EX", true]}]], "expected": ["ok", "ok", "ok", "ok", "ok", "EWOULDBLOCK", "ok", "ok", "ok"]}, {"args": [[{"__tuple__": ["open", "a"]}, {"__tuple__": ["dup", "a", "a2"]}, {"__tuple__": ["flock", "a", "EX", true]}, {"__tuple__": ["flock", "a2", "UN", true]}, {"__tuple__": ["open", "b"]}, {"__tuple__": ["flock", "b", "EX", true]}]], "expected": ["ok", "ok", "ok", "ok", "ok", "ok"]}, {"args": [[{"__tuple__": ["open", "a"]}, {"__tuple__": ["open", "b"]}, {"__tuple__": ["flock", "a", "EX", true]}, {"__tuple__": ["flock", "a", "SH", true]}, {"__tuple__": ["flock", "b", "SH", true]}, {"__tuple__": ["flock", "b", "EX", true]}, {"__tuple__": ["flock", "a", "EX", true]}]], "expected": ["ok", "ok", "ok", "ok", "ok", "EWOULDBLOCK", "ok"]}, {"args": [[]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-move-steps', 7, 'func', 'Что делает shutil.move', 'Напишите move_steps(src, dst, tree, mounts): список шагов, которые выполняет shutil.move(src, dst). tree — словарь «существующий путь → тип» ("f" файл, "d" каталог, "l" символическая ссылка), src в нём есть. mounts — точки монтирования (всегда есть "/"); файловая система пути — самая длинная точка монтирования m, для которой путь равен m или начинается с m + "/" (для несуществующего пути так же). Если dst (без завершающих слэшей) есть в tree и это каталог, цель — real = этот путь + "/" + последний компонент src; если real уже есть в tree, верните [("error", "exists", real)]; иначе real = dst. Если src — каталог и dst (с завершающим слэшем) лежит внутри src (начинается с src + "/"), верните [("rename", src, real, "EINVAL"), ("error", "into-itself", real)]. Если файловые системы src и real совпадают, шаг один: ("rename", src, real). Иначе первый шаг ("rename", src, real, "EXDEV"), а дальше запасной вариант: для файла ("copy2", src, real), ("unlink", src); для каталога ("copytree", src, real), ("rmtree", src); для ссылки ("symlink", src, real), ("unlink", src).', 'def move_steps(src, dst, tree, mounts):
    pass
', 'Порядок проверок такой же, как в shutil.move: целевой каталог, существование, вложение, затем сравнение файловых систем.', '{"func": "move_steps", "tests": [{"args": ["/home/u/notes", "/home/u/notes.bak", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["rename", "/home/u/notes", "/home/u/notes.bak"]}]}, {"args": ["/home/u/notes", "/data/notes", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["rename", "/home/u/notes", "/data/notes", "EXDEV"]}, {"__tuple__": ["copy2", "/home/u/notes", "/data/notes"]}, {"__tuple__": ["unlink", "/home/u/notes"]}]}, {"args": ["/data/db.img", "/mnt/backup", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["rename", "/data/db.img", "/mnt/backup/db.img", "EXDEV"]}, {"__tuple__": ["copy2", "/data/db.img", "/mnt/backup/db.img"]}, {"__tuple__": ["unlink", "/data/db.img"]}]}, {"args": ["/data/db.img", "/data/vm", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["rename", "/data/db.img", "/data/vm/db.img"]}]}, {"args": ["/home/u/proj", "/mnt/backup", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["error", "exists", "/mnt/backup/proj"]}]}, {"args": ["/home/u/proj", "/mnt/backup/", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["error", "exists", "/mnt/backup/proj"]}]}, {"args": ["/home/u/proj", "/home/u/proj/src", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["rename", "/home/u/proj", "/home/u/proj/src/proj", "EINVAL"]}, {"__tuple__": ["error", "into-itself", "/home/u/proj/src/proj"]}]}, {"args": ["/data/ln", "/mnt/usb/ln2", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["rename", "/data/ln", "/mnt/usb/ln2", "EXDEV"]}, {"__tuple__": ["symlink", "/data/ln", "/mnt/usb/ln2"]}, {"__tuple__": ["unlink", "/data/ln"]}]}, {"args": ["/data/ln", "/data/ln2", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["rename", "/data/ln", "/data/ln2"]}]}, {"args": ["/mnt/usb/x", "/mnt/usb", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["error", "exists", "/mnt/usb/x"]}]}, {"args": ["/data/vm", "/home/u/vm-copy", {"/data/db.img": "f", "/data/vm": "d", "/data/ln": "l", "/home/u/notes": "f", "/home/u/proj": "d", "/home/u/proj/src": "d", "/mnt/backup": "d", "/mnt/backup/proj": "d", "/mnt/usb/x": "f", "/mnt/usb": "d", "/mnt/usb/ln": "l"}, ["/", "/data", "/mnt/backup", "/mnt/usb"]], "expected": [{"__tuple__": ["rename", "/data/vm", "/home/u/vm-copy", "EXDEV"]}, {"__tuple__": ["copytree", "/data/vm", "/home/u/vm-copy"]}, {"__tuple__": ["rmtree", "/data/vm"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-copy-plan', 8, 'func', 'Хватит ли места для copytree', 'Напишите copy_plan(entries, free, block, reserve, symlinks): оцените, поместится ли копия дерева. entries — список (путь, тип, размер). Тип "d" — каталог, занимает один блок; "f" — обычный файл размером size байт; "h" — ещё одно имя жёсткой ссылки на уже учтённый файл: copytree копирует каждое имя отдельным файлом, поэтому считается как "f"; "l" — символическая ссылка, size — размер файла, на который она указывает. Файл занимает ceil(size / block) блоков по block байт (пустой файл — 0 блоков). Если symlinks ложно, copytree копирует содержимое цели ссылки как обычный файл, и "l" считается как "f"; если истинно, ссылка воссоздаётся и в этой модели не занимает ничего. need — сумма по всем записям. Если free - need >= reserve, верните ("ok", need); иначе ("ENOSPC", need + reserve - free), то есть сколько байт не хватает.', 'def copy_plan(entries, free, block, reserve, symlinks):
    pass
', 'Округление вверх без float: -(-size // block) * block.', '{"func": "copy_plan", "tests": [{"args": [[{"__tuple__": ["a", "d", 0]}, {"__tuple__": ["a/f1", "f", 100]}, {"__tuple__": ["a/f2", "f", 4096]}, {"__tuple__": ["a/f3", "f", 4097]}], 100000, 4096, 0, false], "expected": {"__tuple__": ["ok", 20480]}}, {"args": [[{"__tuple__": ["a", "d", 0]}, {"__tuple__": ["a/f1", "f", 100]}, {"__tuple__": ["a/f2", "f", 4096]}, {"__tuple__": ["a/f3", "f", 4097]}], 20000, 4096, 4096, false], "expected": {"__tuple__": ["ENOSPC", 4576]}}, {"args": [[{"__tuple__": ["a", "d", 0]}, {"__tuple__": ["a/f1", "f", 100]}, {"__tuple__": ["a/f2", "f", 4096]}, {"__tuple__": ["a/f3", "f", 4097]}], 20480, 4096, 0, false], "expected": {"__tuple__": ["ok", 20480]}}, {"args": [[{"__tuple__": ["a", "d", 0]}, {"__tuple__": ["a/f1", "f", 100]}, {"__tuple__": ["a/f2", "f", 4096]}, {"__tuple__": ["a/f3", "f", 4097]}], 20479, 4096, 0, false], "expected": {"__tuple__": ["ENOSPC", 1]}}, {"args": [[{"__tuple__": ["a/f", "f", 5000]}, {"__tuple__": ["a/h", "h", 5000]}], 16384, 4096, 0, false], "expected": {"__tuple__": ["ok", 16384]}}, {"args": [[{"__tuple__": ["a/f", "f", 5000]}, {"__tuple__": ["a/h", "h", 5000]}], 16383, 4096, 0, false], "expected": {"__tuple__": ["ENOSPC", 1]}}, {"args": [[{"__tuple__": ["a/l", "l", 10000]}, {"__tuple__": ["a/f", "f", 1]}], 12288, 4096, 0, false], "expected": {"__tuple__": ["ENOSPC", 4096]}}, {"args": [[{"__tuple__": ["a/l", "l", 10000]}, {"__tuple__": ["a/f", "f", 1]}], 12288, 4096, 0, true], "expected": {"__tuple__": ["ok", 4096]}}, {"args": [[{"__tuple__": ["a/l", "l", 10000]}, {"__tuple__": ["a/f", "f", 1]}], 4095, 4096, 0, true], "expected": {"__tuple__": ["ENOSPC", 1]}}, {"args": [[{"__tuple__": ["a/empty", "f", 0]}, {"__tuple__": ["a/dir", "d", 0]}, {"__tuple__": ["a/dir/empty", "f", 0]}], 8192, 4096, 8192, false], "expected": {"__tuple__": ["ENOSPC", 4096]}}, {"args": [[], 0, 4096, 0, false], "expected": {"__tuple__": ["ok", 0]}}, {"args": [[], 100, 4096, 200, true], "expected": {"__tuple__": ["ENOSPC", 100]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 22, 'la22-walk-plan', 9, 'func', 'Порядок os.walk и обрезка', 'Напишите walk_plan(tree, root, prune, topdown): список троек (dirpath, dirnames, filenames) в том порядке, в каком их отдаёт os.walk(root, topdown=topdown, followlinks=False), если scandir выдаёт имена по возрастанию. tree — словарь «путь каталога → словарь имя → тип»: "f" файл, "d" каталог, "ld" символическая ссылка на каталог, "lf" символическая ссылка на файл; все каталоги из tree, на которые есть ссылки типа "d", в нём присутствуют. dirnames — имена типов "d" и "ld", filenames — имена типов "f" и "lf", оба списка отсортированы. Путь подкаталога — dirpath + "/" + имя. Ссылки "ld" в списке dirnames есть, но os.walk в них не заходит. При topdown истинном вызывающий перед спуском убирает из dirnames все имена из списка prune (любого уровня, и "d", и "ld"): в тройке остаётся уже урезанный список, а заходят только в оставшиеся "d". При topdown ложном тройка каталога выдаётся после троек всех его подкаталогов типа "d", и урезать список нельзя: prune не действует, dirnames полный.', 'def walk_plan(tree, root, prune, topdown):
    pass
', 'Рекурсия visit(path): при topdown сначала запись, затем спуск; иначе наоборот. Урезайте dirs только при topdown.', '{"func": "walk_plan", "tests": [{"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv", [], true], "expected": [{"__tuple__": ["/srv", ["app", "cache", "zlink"], ["README", "run.sh"]]}, {"__tuple__": ["/srv/app", [".cache", "conf"], ["main.py"]]}, {"__tuple__": ["/srv/app/.cache", ["deep"], ["junk"]]}, {"__tuple__": ["/srv/app/.cache/deep", [], ["x"]]}, {"__tuple__": ["/srv/app/conf", [], ["a.ini"]]}, {"__tuple__": ["/srv/cache", [], ["blob"]]}]}, {"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv", [".cache"], true], "expected": [{"__tuple__": ["/srv", ["app", "cache", "zlink"], ["README", "run.sh"]]}, {"__tuple__": ["/srv/app", ["conf"], ["main.py"]]}, {"__tuple__": ["/srv/app/conf", [], ["a.ini"]]}, {"__tuple__": ["/srv/cache", [], ["blob"]]}]}, {"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv", [".cache", "cache"], true], "expected": [{"__tuple__": ["/srv", ["app", "zlink"], ["README", "run.sh"]]}, {"__tuple__": ["/srv/app", ["conf"], ["main.py"]]}, {"__tuple__": ["/srv/app/conf", [], ["a.ini"]]}]}, {"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv", [".cache"], false], "expected": [{"__tuple__": ["/srv/app/.cache/deep", [], ["x"]]}, {"__tuple__": ["/srv/app/.cache", ["deep"], ["junk"]]}, {"__tuple__": ["/srv/app/conf", [], ["a.ini"]]}, {"__tuple__": ["/srv/app", [".cache", "conf"], ["main.py"]]}, {"__tuple__": ["/srv/cache", [], ["blob"]]}, {"__tuple__": ["/srv", ["app", "cache", "zlink"], ["README", "run.sh"]]}]}, {"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv", [], false], "expected": [{"__tuple__": ["/srv/app/.cache/deep", [], ["x"]]}, {"__tuple__": ["/srv/app/.cache", ["deep"], ["junk"]]}, {"__tuple__": ["/srv/app/conf", [], ["a.ini"]]}, {"__tuple__": ["/srv/app", [".cache", "conf"], ["main.py"]]}, {"__tuple__": ["/srv/cache", [], ["blob"]]}, {"__tuple__": ["/srv", ["app", "cache", "zlink"], ["README", "run.sh"]]}]}, {"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv", ["zlink", "conf"], true], "expected": [{"__tuple__": ["/srv", ["app", "cache"], ["README", "run.sh"]]}, {"__tuple__": ["/srv/app", [".cache"], ["main.py"]]}, {"__tuple__": ["/srv/app/.cache", ["deep"], ["junk"]]}, {"__tuple__": ["/srv/app/.cache/deep", [], ["x"]]}, {"__tuple__": ["/srv/cache", [], ["blob"]]}]}, {"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv/app/conf", [], true], "expected": [{"__tuple__": ["/srv/app/conf", [], ["a.ini"]]}]}, {"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv/app/.cache", ["deep"], true], "expected": [{"__tuple__": ["/srv/app/.cache", [], ["junk"]]}]}, {"args": [{"/srv": {"app": "d", "cache": "d", "zlink": "ld", "README": "f", "run.sh": "lf"}, "/srv/app": {"conf": "d", "main.py": "f", ".cache": "d"}, "/srv/app/conf": {"a.ini": "f"}, "/srv/app/.cache": {"junk": "f", "deep": "d"}, "/srv/app/.cache/deep": {"x": "f"}, "/srv/cache": {"blob": "f"}}, "/srv/app/.cache", ["deep"], false], "expected": [{"__tuple__": ["/srv/app/.cache/deep", [], ["x"]]}, {"__tuple__": ["/srv/app/.cache", ["deep"], ["junk"]]}]}]}');
